```powershell
# PowerShell Script for Safe Directory Backup with Timestamped Naming
param(
    [Parameter(Mandatory=$true)]
    [string]$SourceDirectory,

    [Parameter(Mandatory=$true)]
    [string]$BackupDestination
)

# Validate source directory exists
if (-not (Test-Path -Path $SourceDirectory -PathType Container)) {
    Write-Error "Source directory '$SourceDirectory' does not exist or is not accessible."
    exit 1
}

# Create backup destination if it doesn't exist
if (-not (Test-Path -Path $BackupDestination -PathType Container)) {
    try {
        New-Item -ItemType Directory -Path $BackupDestination -Force | Out-Null
        Write-Host "Created backup destination directory: $BackupDestination"
    }
    catch {
        Write-Error "Failed to create backup destination directory: $BackupDestination"
        exit 1
    }
}

# Generate timestamped backup folder name
$timestamp = Get-Date -Format "yyyyMMdd_HHmmss"
$folderName = Split-Path -Path $SourceDirectory -Leaf
$backupFolderName = "${folderName}_Backup_$timestamp"
$backupPath = Join-Path -Path $BackupDestination -ChildPath $backupFolderName

# Perform the backup
try {
    Write-Host "Starting backup of '$SourceDirectory' to '$backupPath'"

    # Use robocopy for reliable copying with progress indication
    $robocopyArgs = @(
        "`"$SourceDirectory`"",
        "`"$backupPath`"",
        "/E",           # Copy subdirectories including empty ones
        "/COPYALL",     # Copy all file information
        "/R:3",         # Retry 3 times on failed copies
        "/W:5",         # Wait 5 seconds between retries
        "/NP",          # No progress display (for cleaner output)
        "/LOG+:`"$backupPath.log`"",  # Log to file
        "/TEE"          # Output log to console too
    )

    $process = Start-Process -FilePath "robocopy" -ArgumentList $robocopyArgs -NoNewWindow -PassThru -Wait

    if ($process.ExitCode -le 3) {
        # Robocopy exit codes 0-3 indicate success (0=success, 1=files copied, 2=extra files, 3=some files skipped)
        Write-Host "Backup completed successfully: $backupPath" -ForegroundColor Green

        # Verify backup by comparing directory sizes (basic verification)
        $sourceSize = (Get-ChildItem -Path $SourceDirectory -Recurse -File | Measure-Object -Property Length -Sum).Sum
        $backupSize = (Get-ChildItem -Path $backupPath -Recurse -File | Measure-Object -Property Length -Sum).Sum

        if ($sourceSize -eq $backupSize) {
            Write-Host "Backup verification successful - file sizes match" -ForegroundColor Green
        } else {
            Write-Warning "Backup size verification mismatch. Source: $sourceSize bytes, Backup: $backupSize bytes"
        }

        # Create completion marker
        New-Item -ItemType File -Path "$backupPath.backup_complete" | Out-Null

        Write-Host "Backup completed at $(Get-Date)" -ForegroundColor Cyan
        exit 0
    } else {
        Write-Error "Robocopy failed with exit code: $($process.ExitCode)"
        exit 1
    }
}
catch {
    Write-Error "Backup failed: $_"
    exit 1
}
